#!/usr/bin/env bash
# generated by gen_configs.py: sequential train + headcoh queue.
# Re-running is safe: training resumes from the latest checkpoint
# in each run dir (TrainingEnv resume_from = manager.latest_step).
set -uo pipefail
cd "$(dirname "$0")/../.."

run() {
  name="$1"; out="$2"
  echo "=== $name: train ==="
  uv run python experiments/scaling-sweep/train_run.py \
      "experiments/scaling-sweep/configs/$name.json" || exit 1
  echo "=== $name: headcoh ==="
  uv run python headcoh.py --model onto --ckpt "$out" \
      --temperature 0.03 || exit 1
}

run h16_k32_l5 "data/out/sonar/multilingual/scaling/h16_k32_l5"
run h32_k16_l5 "data/out/sonar/multilingual/scaling/h32_k16_l5"
run h32_k32_l3 "data/out/sonar/multilingual/scaling/h32_k32_l3"
run h32_k32_l5 "data/out/sonar/multilingual/scaling/h32_k32_l5"
run h32_k32_l7 "data/out/sonar/multilingual/scaling/h32_k32_l7"
run h32_k64_l5 "data/out/sonar/multilingual/scaling/h32_k64_l5"
run h64_k32_l5 "data/out/sonar/multilingual/scaling/h64_k32_l5"

echo "queue done; now: uv run python experiments/scaling-sweep/analyze.py"
